    /// <summary>The (LEFT, RIGHT) horizontal skyline pair for an accidental kind,
    /// in the glyph's own frame (X from the glyph origin, Y centred on the note).</summary>
    public static (HorizontalSkyline Left, HorizontalSkyline Right) AccidentalSkylinePair(string kind) => kind switch
    {
        "sharp" => (AccSkyPairSharp.Left, AccSkyPairSharp.Right),
        "flat" => (AccSkyPairFlat.Left, AccSkyPairFlat.Right),
        "natural" => (AccSkyPairNatural.Left, AccSkyPairNatural.Right),
        "doubleSharp" => (AccSkyPairDoubleSharp.Left, AccSkyPairDoubleSharp.Right),
        "doubleFlat" => (AccSkyPairDoubleFlat.Left, AccSkyPairDoubleFlat.Right),
        // naturals-as-fallback: an unknown kind draws the natural sign.
        _ => (AccSkyPairNatural.Left, AccSkyPairNatural.Right),
    };

    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairSharp =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkySharpL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkySharpR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairFlat =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyFlatL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyFlatR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairNatural =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyNaturalL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyNaturalR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairDoubleSharp =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyDoubleSharpL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyDoubleSharpR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairDoubleFlat =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyDoubleFlatL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyDoubleFlatR));
}
